attempts = []
def run(job, attempt):
    attempts.append((job.job_id, attempt)); return attempt == 2
result = Scheduler([Job('a', retries=2)], ConcurrencyLimiter(1), run).run()
assert result == {'a': 'succeeded'}
assert attempts == [('a', 0), ('a', 1), ('a', 2)]

def run(job, attempt): return False
result = Scheduler([Job('root'), Job('child', dependencies=('root',)), Job('grandchild', dependencies=('child',)), Job('x', dependencies=('y',)), Job('y', dependencies=('x',))], ConcurrencyLimiter(2), run).run()
